export function getAllowedTransitions(character: keyof typeof transitionGraph, from: string) {
  return transitionGraph[character].allowed.filter((edge) => edge.from === from);
}

export function isTransitionForbidden(
  character: keyof typeof transitionGraph,
  from: string,
  to: string,
) {
  return transitionGraph[character].forbidden.some(
    (edge) => edge.from === from && edge.to === to,
  );
}